    /// The official brand color.
    public var color: Color {
        switch self {
        case .imdb: Color(red: 0.961, green: 0.773, blue: 0.094)  // #F5C518
        case .letterboxd: Color(red: 0.125, green: 0.157, blue: 0.188)  // #202830
        case .metacritic: Color(red: 0.000, green: 0.000, blue: 0.000)  // #000000
        case .rottentomatoes: Color(red: 0.980, green: 0.196, blue: 0.039)  // #FA320A
        case .themoviedatabase: Color(red: 0.004, green: 0.706, blue: 0.894)  // #01B4E4
        }
