    /// Relative luminance of `color` (0 black … 1 white). A brand whose
    /// official color is near-black - GitHub's #181717, Metacritic's
    /// #000000 - vanishes on a dark surface, and the answer there is a
    /// shape-based treatment or an explicit tint, never a silent repaint
    /// of someone's logo.
    public var luminance: Double {
        switch self {
        case .imdb: 0.764
        case .letterboxd: 0.152
        case .metacritic: 0.000
        case .rottentomatoes: 0.351
        case .themoviedatabase: 0.570
        }
    }

    /// Width over height of the artwork, from its viewBox. A symbol
    /// (≈1) sits in a disc; a lockup (≫1) runs inline with text.
    public var aspect: Double {
        switch self {
        case .imdb: 1.000
        case .letterboxd: 1.000
        case .metacritic: 1.000
        case .rottentomatoes: 1.000
        case .themoviedatabase: 1.000
        }
    }

    /// Marks whose own colours ARE the mark (a flag, not a logo): rendered
    /// as authored, never template-tinted, whatever the caller passes.
    public var original: Bool {
        false
    }

    #if canImport(AppKit)
        /// The artwork as AppKit sees it. Under Xcode the catalog is compiled
        /// and the named lookup answers; under `swift build` the catalog rides
        /// the bundle as a RAW folder (no actool), so the SVG is read straight
        /// from `Brands.xcassets/<slug>.imageset/<slug>.svg` - macOS renders SVG natively.
        public var nsImage: NSImage? {
            if let compiled = Bundle.module.image(forResource: rawValue) { return compiled }
            guard
                let url = Bundle.module.url(
                    forResource: rawValue, withExtension: "svg",
                    subdirectory: "Brands.xcassets/\(rawValue).imageset"),
